import React, { useState, useRef } from 'react';
import DashboardLayout from '../components/DashboardLayout';

const DISEASE_DB = {
  fungal: { name: 'Wheat Rust (Fungal)', icon: '🍂', confidence: 87, severity: 'Moderate', type: 'Fungal Infection', color: 'yellow',
    symptoms: 'Orange-brown pustules on leaves and stems. Yellowing of leaf tissue around pustules.',
    treatment: ['Apply Propiconazole 25 EC @ 0.1% spray', 'Remove and destroy infected plant parts', 'Improve air circulation between rows', 'Avoid overhead irrigation'],
    medicines: ['Propiconazole (Tilt)', 'Tebuconazole (Folicur)', 'Mancozeb (Dithane M-45)'],
    prevention: 'Use rust-resistant varieties. Apply preventive fungicide before monsoon. Maintain proper plant spacing.' },
  pest: { name: 'Aphid Infestation', icon: '🐛', confidence: 92, severity: 'High', type: 'Pest Attack', color: 'red',
    symptoms: 'Clusters of small green/black insects on leaves. Sticky honeydew residue. Curled, yellowing leaves.',
    treatment: ['Spray Imidacloprid 17.8 SL @ 0.3ml/L', 'Apply Thiamethoxam 25 WG @ 0.2g/L', 'Use neem oil spray (5ml/L) as organic option', 'Introduce natural predators (ladybirds)'],
    medicines: ['Imidacloprid (Confidor)', 'Thiamethoxam (Actara)', 'Neem Oil (organic)'],
    prevention: 'Monitor crops weekly. Avoid excess nitrogen fertilizer. Maintain beneficial insect habitat.' },
  nutrient: { name: 'Nitrogen Deficiency', icon: '🟡', confidence: 78, severity: 'Moderate', type: 'Nutrient Deficiency', color: 'yellow',
    symptoms: 'Yellowing starting from older/lower leaves. Pale green color overall. Stunted growth and thin stems.',
    treatment: ['Apply Urea 25kg/acre as top dressing', 'Foliar spray: 2% Urea solution', 'Add organic matter (FYM 5 tonnes/acre)', 'Irrigate after fertilizer application'],
    medicines: ['Urea (46% N)', 'Ammonium Sulphate', 'Liquid Nitrogen Fertilizer'],
    prevention: 'Conduct soil test before sowing. Apply balanced NPK fertilizer. Practice crop rotation with legumes.' },
};

const RISK_ZONES = [
  { crop: 'Wheat', disease: 'Rust', risk: 'Medium', probability: 45, icon: '🌾', color: '#f59e0b' },
  { crop: 'Cotton', disease: 'Bollworm', risk: 'High', probability: 72, icon: '🌿', color: '#ef4444' },
  { crop: 'Rice', disease: 'Blast', risk: 'Low', probability: 18, icon: '🍚', color: '#22c55e' },
  { crop: 'Tomato', disease: 'Blight', risk: 'High', probability: 68, icon: '🍅', color: '#ef4444' },
];

export default function DiseaseScannerPage() {
  const [image, setImage] = useState(null);
  const [preview, setPreview] = useState(null);
  const [scanning, setScanning] = useState(false);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState(null);
  const [dragging, setDragging] = useState(false);
  const [detectionType, setDetectionType] = useState('fungal');
  const fileRef = useRef();

  const handleFile = (file) => {
    if (!file || !file.type.startsWith('image/')) return;
    setImage(file); setPreview(URL.createObjectURL(file)); setResult(null);
  };

  const scan = () => {
    setScanning(true); setProgress(0);
    const interval = setInterval(() => {
      setProgress(p => {
        if (p >= 100) { clearInterval(interval); setScanning(false); setResult(DISEASE_DB[detectionType]); return 100; }
        return p + Math.random() * 12;
      });
    }, 180);
  };

  const reset = () => { setImage(null); setPreview(null); setResult(null); setProgress(0); };

  const severityColor = { Low: 'text-green-400 border-green-500/30 bg-green-900/20', Moderate: 'text-yellow-400 border-yellow-500/30 bg-yellow-900/20', High: 'text-red-400 border-red-500/30 bg-red-900/20' };
  const typeColor = { 'Fungal Infection': 'text-orange-400', 'Pest Attack': 'text-red-400', 'Nutrient Deficiency': 'text-yellow-400' };

  return (
    <DashboardLayout title="Disease Prediction System" subtitle="AI-powered crop disease detection — fungal, pests & nutrient deficiencies">

      {/* Detection Type Selector */}
      <div className="glass rounded-2xl p-4 mb-5 border border-green-900/30">
        <div className="text-gray-400 text-xs uppercase tracking-wider mb-3">Detection Mode</div>
        <div className="flex gap-3 flex-wrap">
          {[
            { key: 'fungal', icon: '🍂', label: 'Fungal Infections', color: 'border-orange-700/40' },
            { key: 'pest', icon: '🐛', label: 'Pest Detection', color: 'border-red-700/40' },
            { key: 'nutrient', icon: '🟡', label: 'Nutrient Deficiency', color: 'border-yellow-700/40' },
          ].map(t => (
            <button key={t.key} onClick={() => setDetectionType(t.key)}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-medium transition-all border ${detectionType === t.key ? `btn-primary text-white ${t.color}` : `glass-dark text-gray-400 hover:text-white ${t.color}`}`}>
              <span>{t.icon}</span>{t.label}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
        {/* Upload */}
        <div className="space-y-4">
          {!preview ? (
            <div onDragOver={e => { e.preventDefault(); setDragging(true); }}
              onDragLeave={() => setDragging(false)}
              onDrop={e => { e.preventDefault(); setDragging(false); handleFile(e.dataTransfer.files[0]); }}
              onClick={() => fileRef.current?.click()}
              className={`glass rounded-2xl border-2 border-dashed p-12 text-center cursor-pointer transition-all ${dragging ? 'border-green-400 bg-green-900/20' : 'border-green-900/40 hover:border-green-700/60 hover:bg-green-900/10'}`}>
              <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={e => handleFile(e.target.files[0])} />
              <div className="text-6xl mb-4 animate-float">🔬</div>
              <div className="text-white font-semibold text-lg mb-2">Upload Crop / Leaf Photo</div>
              <div className="text-gray-400 text-sm mb-4">Drag & drop or click to upload<br />JPG, PNG, WEBP supported</div>
              <div className="btn-primary text-white text-sm font-semibold px-6 py-2.5 rounded-xl inline-block">Choose Photo</div>
            </div>
          ) : (
            <div className="glass rounded-2xl overflow-hidden border border-green-900/30">
              <div className="relative">
                <img src={preview} alt="crop" className="w-full h-64 object-cover" />
                {scanning && (
                  <div className="absolute inset-0 bg-black/70 flex flex-col items-center justify-center">
                    <div className="w-16 h-16 border-4 border-green-400 border-t-transparent rounded-full animate-spin mb-4" />
                    <div className="text-green-400 font-semibold mb-3">AI Analyzing {detectionType}...</div>
                    <div className="w-48 h-2 bg-black/40 rounded-full overflow-hidden">
                      <div className="h-full bg-gradient-to-r from-green-600 to-green-400 rounded-full transition-all" style={{ width: `${Math.min(progress, 100)}%` }} />
                    </div>
                    <div className="text-gray-400 text-xs mt-2">{Math.min(Math.round(progress), 100)}%</div>
                  </div>
                )}
              </div>
              <div className="p-4 flex gap-3">
                <button onClick={scan} disabled={scanning}
                  className={`flex-1 btn-primary text-white font-semibold py-3 rounded-xl flex items-center justify-center gap-2 ${scanning ? 'opacity-60' : ''}`}>
                  {scanning ? '⟳ Scanning...' : '🔬 Detect Disease'}
                </button>
                <button onClick={reset} className="glass-dark border border-green-900/40 text-gray-400 hover:text-white px-4 py-3 rounded-xl transition-all">✕</button>
              </div>
            </div>
          )}

          {/* Disease Risk Zones */}
          <div className="glass rounded-2xl p-5 border border-green-900/30">
            <h4 className="font-semibold text-white text-sm mb-3">⚠️ Disease Risk in Your Zone</h4>
            <div className="space-y-3">
              {RISK_ZONES.map((r, i) => (
                <div key={i} className="flex items-center gap-3">
                  <span className="text-xl">{r.icon}</span>
                  <div className="flex-1">
                    <div className="flex justify-between text-xs mb-1">
                      <span className="text-gray-300">{r.crop} — {r.disease}</span>
                      <span className="font-bold" style={{ color: r.color }}>{r.risk}</span>
                    </div>
                    <div className="h-1.5 bg-black/40 rounded-full overflow-hidden">
                      <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${r.probability}%`, background: r.color }} />
                    </div>
                  </div>
                  <span className="text-xs text-gray-500 w-8">{r.probability}%</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Results */}
        <div>
          {!result ? (
            <div className="glass rounded-2xl p-10 border border-green-900/30 text-center h-full flex flex-col items-center justify-center">
              <div className="text-6xl mb-4">🌿</div>
              <div className="text-white font-semibold text-lg mb-2">No Scan Yet</div>
              <div className="text-gray-400 text-sm mb-6">Upload a photo of your crop leaf or plant to detect diseases instantly with 95% accuracy.</div>
              <div className="grid grid-cols-3 gap-3 w-full max-w-xs">
                {[['95%', 'Accuracy'], ['50+', 'Diseases'], ['< 5s', 'Speed']].map(([v, l]) => (
                  <div key={l} className="glass-dark rounded-xl p-3 text-center">
                    <div className="text-green-400 font-bold text-lg">{v}</div>
                    <div className="text-gray-500 text-xs">{l}</div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="space-y-4 animate-fade-in">
              {/* Disease Header */}
              <div className={`glass rounded-2xl p-5 border ${result.color === 'red' ? 'border-red-700/30 bg-red-900/5' : 'border-yellow-700/30 bg-yellow-900/5'}`}>
                <div className="flex items-start justify-between mb-3">
                  <div className="flex items-center gap-3">
                    <span className="text-4xl">{result.icon}</span>
                    <div>
                      <h3 className="font-display font-bold text-xl text-white">{result.name}</h3>
                      <span className={`text-xs font-semibold ${typeColor[result.type]}`}>{result.type}</span>
                    </div>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-xs font-bold border ${severityColor[result.severity]}`}>{result.severity}</span>
                </div>
                <div className="glass-dark rounded-xl p-3 mb-3">
                  <div className="flex justify-between text-xs text-gray-400 mb-1"><span>AI Confidence</span><span>{result.confidence}%</span></div>
                  <div className="h-2 bg-black/40 rounded-full overflow-hidden">
                    <div className="h-full bg-gradient-to-r from-yellow-600 to-yellow-400 rounded-full" style={{ width: `${result.confidence}%` }} />
                  </div>
                </div>
                <div className="text-gray-300 text-sm"><span className="text-gray-500">Symptoms: </span>{result.symptoms}</div>
              </div>

              {/* Treatment */}
              <div className="glass rounded-2xl p-5 border border-green-900/30">
                <h4 className="font-semibold text-white mb-3 flex items-center gap-2"><span>💊</span> Treatment Steps</h4>
                <div className="space-y-2 mb-4">
                  {result.treatment.map((t, i) => (
                    <div key={i} className="flex items-start gap-3 p-2">
                      <div className="w-5 h-5 rounded-full bg-green-500/20 border border-green-500/40 flex items-center justify-center text-green-400 text-xs flex-shrink-0 mt-0.5">{i + 1}</div>
                      <span className="text-gray-300 text-sm">{t}</span>
                    </div>
                  ))}
                </div>
                <div className="border-t border-green-900/30 pt-3">
                  <div className="text-gray-400 text-xs mb-2 font-semibold">Recommended Medicines</div>
                  <div className="flex flex-wrap gap-2">
                    {result.medicines.map((m, i) => (
                      <span key={i} className="glass-green text-green-300 text-xs px-3 py-1 rounded-full border border-green-700/30">{m}</span>
                    ))}
                  </div>
                </div>
              </div>

              {/* Prevention */}
              <div className="glass-green rounded-2xl p-4 border border-green-700/30">
                <h4 className="font-semibold text-green-300 mb-2 flex items-center gap-2"><span>🛡️</span> Prevention</h4>
                <p className="text-gray-300 text-sm">{result.prevention}</p>
              </div>

              <button onClick={reset} className="w-full glass border border-green-900/40 text-green-400 font-semibold py-3 rounded-xl hover:bg-green-900/20 transition-all">
                🔬 Scan Another Photo
              </button>
            </div>
          )}
        </div>
      </div>
    </DashboardLayout>
  );
}
